/usr/bin/bash -lc "cat > /tmp/pomodoro-browser-check/check.cjs <<'EOF'
const { chromium } = require('playwright');
const assert = require('node:assert/strict');
const { pathToFileURL } = require('node:url');
(async () => {
  const browser = await chromium.launch({ args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1440, height: 1000 }, colorScheme: 'light', deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  const initialTime = new Date('2026-10-29T12:00:00Z');
  await page.clock.install({ time: initialTime });
  await page.clock.pauseAt(initialTime);
  await page.goto(pathToFileURL('/work/pm2-a/timer.html').href);
  const time = page.locator('#time');
  const start = page.getByRole('button', { name: '开始' });
  const pause = page.getByRole('button', { name: '暂停' });
  const reset = page.getByRole('button', { name: '重置' });
  assert.equal(await page.getByRole('button').count(), 3);
  assert.equal(await time.textContent(), '25:00');
  assert.equal(await pause.isDisabled(), true);
  assert.equal(await start.isEnabled(), true);
  await page.screenshot({ path: '/tmp/pomodoro-browser-check/light.png', fullPage: true });
  await start.click();
  assert.equal(await start.isDisabled(), true);
  assert.equal(await pause.isEnabled(), true);
  await page.clock.runFor(1250);
  assert.equal(await time.textContent(), '24:59');
  await pause.click();
  assert.equal(await page.locator('#status').textContent(), '已暂停');
  await page.clock.fastForward(300000);
  assert.equal(await time.textContent(), '24:59');
  await start.click();
  await page.clock.runFor(1000);
  assert.equal(await time.textContent(), '24:58');
  await reset.click();
  assert.equal(await time.textContent(), '25:00');
  await page.clock.fastForward(10000);
  assert.equal(await time.textContent(), '25:00');
  await start.click();
  await page.clock.fastForward(25 * 60 * 1000);
  assert.equal(await time.textContent(), '00:00');
  assert.equal(await page.locator('#status').textContent(), '本轮完成');
  assert.equal(await pause.isDisabled(), true);
  assert.equal(await page.locator('#progress').evaluate(el => el.style.opacity), '0');
  await page.clock.fastForward(60000);
  assert.equal(await time.textContent(), '00:00');
  await start.click();
  assert.equal(await time.textContent(), '25:00');
  await reset.click();
  await page.emulateMedia({ colorScheme: 'dark', reducedMotion: 'reduce' });
  assert.equal(await page.evaluate(() => matchMedia('(prefers-color-scheme: dark)').matches), true);
  await page.screenshot({ path: '/tmp/pomodoro-browser-check/dark.png', fullPage: true });
  for (const width of [390, 320]) {
    await page.setViewportSize({ width, height: 844 });
    assert.equal(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth), true, "'`no overflow at ${width}px`);
    for (const button of [start, pause, reset]) {
      const box = await button.boundingBox();
      assert.ok(box && box.width >= 44 && box.height >= 44 && box.x >= 0 && box.x + box.width <= width);
    }
    await page.screenshot({ path: `/tmp/pomodoro-browser-check/mobile-${width}.png`, fullPage: true });
  }
  await page.emulateMedia({ colorScheme: '"'light' });
  await page.screenshot({ path: '/tmp/pomodoro-browser-check/mobile-light.png', fullPage: true });
  await page.keyboard.press('Tab');
  assert.equal(await start.evaluate(el => el === document.activeElement), true);
  await page.keyboard.press('Enter');
  assert.equal(await page.locator('#status').textContent(), '专注中');
  assert.deepEqual(errors, []);
  console.log('PASS: Initial 25:00, start, pause stability, resume, reset, full 25-minute completion, restart, keyboard, light/dark themes, 390/320px layouts, no JavaScript errors.');
  await browser.close();
})().catch(error => { console.error(error); process.exitCode = 1; });
EOF"

