  assert.equal(await long.getAttribute('aria-pressed'), 'false');
  await start.click();
  assert.equal(await page.locator('#status').textContent(), '进行中');
  assert.equal(await short.isDisabled(), true);
  assert.equal(await long.isDisabled(), true);
  await page.waitForTimeout(300);
  await pause.click();
  assert.equal(await page.locator('#status').textContent(), '已暂停');
  assert.equal(await short.isDisabled(), false);
  await long.click();
  assert.equal(await time.textContent(), '15:00');
  assert.equal(await page.locator('#session').textContent(), '长休息 / LONG BREAK');
  await reset.click();
  assert.equal(await time.textContent(), '15:00');
  await page.emulateMedia({ colorScheme: 'dark' });
  assert.equal(await page.locator('body').evaluate(el => getComputedStyle(el).backgroundColor), 'rgb(22, 32, 26)');
  await page.screenshot({ path: '/tmp/pomodoro-browser-check/updated-dark.png', fullPage: true });
  for (const width of [390, 320]) {
    await page.setViewportSize({ width, height: 844 });
    assert.equal(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth), true, "'`no overflow at ${width}px`);
    for (const button of [start, pause, reset, short, long]) {
      const box = await button.boundingBox();
      assert.ok(box && box.width >= 44 && box.height >= 42 && box.x >= 0 && box.x + box.width <= width);
    }
  }
  assert.deepEqual(errors, []);
  console.log('"'PASS: 5-minute and 15-minute modes, reset/start/pause behavior, non-cramped spacing, light/dark green backgrounds, and 390/320px layouts.');
  await browser.close();
})().catch(error => { console.error(error); process.exitCode = 1; });
